function init() {
}

function loop() {
    if (player.queued > 0) return;

    const target = world.vision.find(e => e.type === "bot");
    if (!target) return;

    const dx = target.x - player.x;
    const dy = target.y - player.y;

    if (Math.abs(dx) + Math.abs(dy) === 1) {
        player.attackClosest();
    } else if (Math.abs(dx) > Math.abs(dy)) {
        player.move(dx > 0 ? "right" : "left");
    } else {
        player.move(dy > 0 ? "down" : "up");
    }
}

function init() {
    ui.onKey((key) => {
        if (key == "w") player.move("up");
        else if (key == "a") player.move("left");
        else if (key == "s") player.move("down");
        else if (key == "d") player.move("right");
        else if (key == " ") player.attackClosest();
    });
}

